    let days = sec / (60 * 60 * 24)
    sec %= 60 * 60 * 24
    let hrs = sec / (60 * 60)
    sec %= 60 * 60
    let mins = sec / 60
    sec %= 60

    put("\t", out)
    if days != 0 {
      put("\(days)d", out)
    }
    if hrs != 0 {
      put("\(hrs)h", out)
    }
    if mins != 0 {
      put("\(mins)m", out)
    }
    put("\(sec)\(decimal_point)\(field(centisec, 2, "0"))s", out)
  }

  func showtime(_ out: UnsafeMutablePointer<FILE>, _ before: timespec, _ after: inout timespec, _ ru: rusage) {
